const renderSlide=(ctx,slide,idx,total,logo)=>{const W=1080,H=1080;ctx.clearRect(0,0,W,H);const colors={cover:{bg:"#0A3328",accent:"#00796B",text:"#FFFFFF"},stat:{bg:"#FDFBF9",accent:"#0A3328",text:"#1A1A1A"},content:{bg:"#FFFFFF",accent:"#0A3328",text:"#1A1A1A"},quote:{bg:"#00796B",accent:"#B8956F",text:"#FFFFFF"},cta:{bg:"#0A3328",accent:"#9B7653",text:"#FFFFFF"}};const c=colors[slide.type]||colors.content;ctx.fillStyle=c.bg;ctx.fillRect(0,0,W,H);if(slide.type==="cover"||slide.type==="cta"){const grd=ctx.createLinearGradient(0,0,W,H);grd.addColorStop(0,c.bg);grd.addColorStop(1,slide.type==="cover"?"#0D4A3A":"#142E24");ctx.fillStyle=grd;ctx.fillRect(0,0,W,H);ctx.fillStyle=c.accent+"20";ctx.beginPath();ctx.arc(W*0.85,H*0.15,200,0,Math.PI*2);ctx.fill();ctx.beginPath();ctx.arc(W*0.1,H*0.9,150,0,Math.PI*2);ctx.fill()}if(slide.type==="stat"){ctx.fillStyle="#0A332808";ctx.fillRect(0,0,W,H*0.06);ctx.fillRect(0,H*0.94,W,H*0.06)}const isDark=slide.type==="cover"||slide.type==="quote"||slide.type==="cta";if(logo&&isDark){const lh=28;const lw=lh*(logo.naturalWidth/logo.naturalHeight);ctx.drawImage(logo,60,60,lw,lh);ctx.font="400 14px 'DM Sans',sans-serif";ctx.fillStyle="#FFFFFF50";ctx.textAlign="left";ctx.fillText("AI Growth Engine",60+lw+12,82)}else{ctx.fillStyle=isDark?c.accent:"#0A3328";ctx.fillRect(60,60,4,28);ctx.font="700 18px 'DM Sans',sans-serif";ctx.fillStyle=isDark?c.text+"DD":"#0A3328";ctx.textAlign="left";ctx.fillText("NEWTEC",80,82);ctx.font="400 14px 'DM Sans',sans-serif";ctx.fillStyle=isDark?"#FFFFFF50":"#A3988860";ctx.fillText("AI Growth Engine",168,82)}ctx.textAlign="right";ctx.font="500 15px 'JetBrains Mono',monospace";ctx.fillStyle=c.text+"50";ctx.fillText(`${idx+1} / ${total}`,W-60,H-50);ctx.fillStyle=isDark?c.accent:c.accent+"30";ctx.fillRect(60,H-36,W-120,1);ctx.textAlign="left";if(slide.type==="cover"){ctx.font="700 64px 'Playfair Display',serif";ctx.fillStyle=c.text;wrapText(ctx,slide.headline||"",80,H*0.38,W-160,76);ctx.fillStyle=c.accent;ctx.fillRect(80,H*0.55,80,4);ctx.font="400 28px 'DM Sans',sans-serif";ctx.fillStyle=c.text+"CC";wrapText(ctx,slide.subtitle||"",80,H*0.63,W-160,38)}else if(slide.type==="stat"){ctx.font="700 120px 'JetBrains Mono',monospace";ctx.fillStyle="#0A3328";ctx.textAlign="center";ctx.fillText(slide.stat_value||"",W/2,H*0.42);ctx.fillStyle="#00796B";ctx.fillRect(W/2-40,H*0.46,80,4);ctx.font="600 28px 'DM Sans',sans-serif";ctx.fillStyle="#6B6259";ctx.fillText(slide.stat_label||"",W/2,H*0.54);if(slide.context){ctx.font="400 22px 'DM Sans',sans-serif";ctx.fillStyle="#A39888";wrapText(ctx,slide.context,140,H*0.62,W-280,32)}ctx.textAlign="left"}else if(slide.type==="content"){ctx.font="700 44px 'Playfair Display',serif";ctx.fillStyle=c.text;wrapText(ctx,slide.headline||"",80,200,W-160,54);const lines=slide.lines||[];let y=340;lines.forEach(line=>{ctx.fillStyle=c.accent;ctx.beginPath();ctx.arc(100,y-6,6,0,Math.PI*2);ctx.fill();ctx.font="400 26px 'DM Sans',sans-serif";ctx.fillStyle="#4A4A4A";wrapText(ctx,line,124,y,W-200,36);y+=90})}else if(slide.type==="quote"){ctx.font="700 140px 'Playfair Display',serif";ctx.fillStyle=c.accent+"40";ctx.fillText('"',60,200);ctx.font="italic 600 38px 'Playfair Display',serif";ctx.fillStyle=c.text;wrapText(ctx,slide.text||"",100,300,W-200,52);if(slide.attribution){ctx.font="500 22px 'DM Sans',sans-serif";ctx.fillStyle=c.text+"90";ctx.fillText("\u2014 "+slide.attribution,100,H*0.75)}}else if(slide.type==="cta"){ctx.font="700 52px 'Playfair Display',serif";ctx.fillStyle=c.text;wrapText(ctx,slide.headline||"",80,H*0.32,W-160,64);ctx.fillStyle=c.accent;ctx.fillRect(80,H*0.52,80,4);ctx.font="400 26px 'DM Sans',sans-serif";ctx.fillStyle=c.text+"CC";wrapText(ctx,slide.subtitle||"",80,H*0.60,W-160,36);if(slide.action){ctx.fillStyle=c.accent;const ax=80,ay=H*0.72,aw=360,ah=56;ctx.beginPath();ctx.roundRect(ax,ay,aw,ah,10);ctx.fill();ctx.font="700 22px 'DM Sans',sans-serif";ctx.fillStyle="#FFFFFF";ctx.textAlign="center";ctx.fillText(slide.action,ax+aw/2,ay+36);ctx.textAlign="left"}}};
const wrapText=(ctx,text,x,y,maxW,lineH)=>{const words=text.split(" ");let line="";let cy=y;for(const w of words){const test=line+w+" ";if(ctx.measureText(test).width>maxW&&line){ctx.fillText(line.trim(),ctx.textAlign==="center"?x:x,cy);cy+=lineH;line=w+" "}else{line=test}}if(line)ctx.fillText(line.trim(),ctx.textAlign==="center"?x:x,cy);return cy};
